// Social Media Post Validator
// Bug: Validations should only run with logErrors when outputMode is 'lint'
// Currently running validations regardless of outputMode

function runPostValidation(env, post) {
  const hir = post.content;

  // Validation 1: Check for profanity
  if (env.config.validateProfanity) {
    env.logErrors(validateProfanity(hir));
  }

  // Validation 2: Check for spam patterns
  if (env.config.validateSpamPatterns && env.outputMode === 'lint') {
    env.logErrors(validateSpamPatterns(hir));
  }

  // Validation 3: Check for external links
  if (env.config.validateExternalLinks) {
    env.logErrors(validateExternalLinks(hir));
  }

  // Validation 4: Check for hashtag usage
  if (env.config.validateHashtagUsage) {
    env.logErrors(validateHashtagUsage(hir));
  }

  // Validation 5: Check for static content optimization
  if (env.enableValidations && env.config.validateStaticContent) {
    env.logErrors(validateStaticContent(hir));
  }

  return {
    status: 'validated',
    value: hir
  };
}

// Mock validation functions (simplified for challenge)
function validateProfanity(content) {
  return content.includes('badword') ? 'Profanity detected' : null;
}

function validateSpamPatterns(content) {
  return content.includes('buy now') ? 'Spam pattern detected' : null;
}

function validateExternalLinks(content) {
  return content.includes('http://') ? 'External link detected' : null;
}

function validateHashtagUsage(content) {
  return content.includes('#') ? 'Hashtag usage detected' : null;
}

function validateStaticContent(content) {
  return content.length > 1000 ? 'Content too long for static optimization' : null;
}

export { runPostValidation };

