import { runPostValidation } from './validator.js';

// Test environment setup
function createTestEnv(config, outputMode, enableValidations) {
  const errors = [];
  return {
    config,
    outputMode,
    enableValidations,
    logErrors: (result) => {
      if (result) errors.push(result);
    },
    getErrors: () => errors
  };
}

console.log('Running tests...\n');

// Test 1: Validation should run in 'lint' mode
console.log('Test 1: Validations run in lint mode');
const env1 = createTestEnv(
  { validateSpamPatterns: true, validateExternalLinks: true },
  'lint',
  true
);
runPostValidation(env1, { content: 'Test post with buy now and http://link' });
const errors1 = env1.getErrors();
console.log(`Expected 2 errors, got: ${errors1.length}`);
console.log(errors1.includes('Spam pattern detected') ? '✓ Spam validation ran' : '✗ Spam validation failed');
console.log(errors1.includes('External link detected') ? '✓ External link validation ran' : '✗ External link validation failed');

// Test 2: Validation should NOT run in 'production' mode
console.log('\nTest 2: Validations skip in production mode');
const env2 = createTestEnv(
  { validateSpamPatterns: true, validateExternalLinks: true },
  'production',
  true
);
runPostValidation(env2, { content: 'Test post with buy now and http://link' });
const errors2 = env2.getErrors();
console.log(`Expected 0 errors, got: ${errors2.length}`);
console.log(errors2.length === 0 ? '✓ Validations skipped correctly' : '✗ Validations ran when they should not');

// Test 3: Mixed validations with different configs
console.log('\nTest 3: Mixed validation configs');
const env3 = createTestEnv(
  { validateProfanity: true, validateSpamPatterns: false, validateExternalLinks: true },
  'lint',
  true
);
runPostValidation(env3, { content: 'badword post with http://link' });
const errors3 = env3.getErrors();
console.log(`Expected 2 errors, got: ${errors3.length}`);
console.log(errors3.includes('Profanity detected') ? '✓ Profanity validation ran' : '✗ Profanity validation failed');
console.log(errors3.includes('External link detected') ? '✓ External link validation ran' : '✗ External link validation failed');

// Test 4: Static content validation with enableValidations
console.log('\nTest 4: Static content validation');
const env4 = createTestEnv(
  { validateStaticContent: true },
  'lint',
  true
);
runPostValidation(env4, { content: 'x'.repeat(1001) });
const errors4 = env4.getErrors();
console.log(`Expected 1 error, got: ${errors4.length}`);
console.log(errors4.includes('Content too long for static optimization') ? '✓ Static content validation ran' : '✗ Static content validation failed');

// Test 5: Static content validation should NOT run in production
console.log('\nTest 5: Static content validation skips in production');
const env5 = createTestEnv(
  { validateStaticContent: true },
  'production',
  true
);
runPostValidation(env5, { content: 'x'.repeat(1001) });
const errors5 = env5.getErrors();
console.log(`Expected 0 errors, got: ${errors5.length}`);
console.log(errors5.length === 0 ? '✓ Static validation skipped correctly' : '✗ Static validation ran when it should not');

console.log('\n=== Summary ===');
console.log('All tests should pass after fixing the bug.');
console.log('The bug is that some validations run regardless of outputMode.');
console.log('Fix by adding && env.outputMode === \'lint\' to appropriate conditions.');
